import sympy

def sum_gcd(M):
    s = 0
    for d in range(1, M + 1):
        if M % d == 0:
            s += d * sympy.totient(M // d)
    return s

for M in range(2, 1001):
    if sum_gcd(M) == 2 * M:
        print(f"M={M}, N={M-1}")

def S_calc(N):
    s = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            s += (a * b) // (N + 1)
    return s

for N in [3, 7, 11]:
    S = S_calc(N)
    formula = (N**3 - N**2 + 2) / 4
